package com.bank.coupon;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class CouponRedemptionPlanner {

    private static final Logger log = Logger.getLogger(CouponRedemptionPlanner.class.getName());

    public List<List<Integer>> combinationSum2(int[] coupons, int target) {
        Arrays.sort(coupons);
        List<List<Integer>> result = new ArrayList<>();
        backtrack(coupons, 0, target, new ArrayList<>(), result);
        log.info(() -> "Found " + result.size() + " redemption sets for target " + target);
        return result;
    }

    private void backtrack(int[] cand, int start, int remain,
                           List<Integer> path, List<List<Integer>> result) {
        if (remain == 0) { result.add(new ArrayList<>(path)); return; }
        for (int i = start; i < cand.length; i++) {
            if (i > start && cand[i] == cand[i - 1]) continue; // same-level duplicate
            if (cand[i] > remain) break;                       // sorted prune
            path.add(cand[i]);
            backtrack(cand, i + 1, remain - cand[i], path, result); // i+1 ⇒ use once
            path.remove(path.size() - 1);
        }
    }
}
