package com.bank.coupon;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CombinationSumIIDemo {

    private static final Logger log = Logger.getLogger(CombinationSumIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Coupon Redemption Planner (Combination Sum II)");
        int[] coupons = {10, 1, 2, 7, 6, 1, 5}; // duplicate coupon value 1
        int target = 8;
        CouponRedemptionPlanner p = new CouponRedemptionPlanner();
        p.combinationSum2(coupons, target).forEach(s -> log.info("Set: " + s));
    }
}
